// The proposed solution of an initiative, one entry per intervention, edited by people and shared with the team.
// An entry starts from what the other sections already know (imported detail, confirmed rationale, documents)
// but every field is the user's: nothing here is generated by the app, and nothing is invented.

export const SOLUTION_FIELDS = [
  ['approach', 'Soluzione proposta', 'Come si realizza l’intervento: componenti toccati, flusso, scelte tecniche.'],
  ['constraints', 'Vincoli e dipendenze', 'Cosa limita la soluzione e da chi o da cosa dipende.'],
  ['assumptions', 'Ipotesi da verificare', 'Ciò che si sta assumendo senza averlo ancora confermato.'],
  ['tests', 'Verifiche e criteri di accettazione', 'Come si capisce che l’intervento è fatto bene.'],
  ['notes', 'Note per chi sviluppa', 'Indicazioni libere: file da guardare, attenzioni, riferimenti.'],
];
export const FIELD_KEYS = SOLUTION_FIELDS.map(([key]) => key);
export const MAX_FIELD = 6000;
export const MAX_SUMMARY = 1500;

export const interventionKey = id => String(id ?? '').trim();

export const emptyEntry = () => Object.fromEntries(FIELD_KEYS.map(key => [key, '']));
export const isEmptyEntry = entry => !entry || FIELD_KEYS.every(key => !String(entry[key] || '').trim());

// Interventions as the Excel import describes them. The same shape is used by the page and by this module.
export function interventionList(interventions) {
  return (interventions || []).map(x => ({
    id: interventionKey(x.id), title: String(x.titolo || x.title || '').trim(), description: String(x.descrizione || x.description || '').trim(),
    activity: String(x.attivita || x.activity || '').trim(), system: String(x.sistema || x.system || '').trim(), requirements: String(x.requisiti || x.requirements || '').trim(),
    mappings: (x.mappings || []).map(m => ({ name: String(m.name || '').trim(), type: m.type || '', complexity: m.complexity || '', qty: Number(m.qty) || 0, component: String(m.componentApplication || '').trim(),
      technology: String(m.technology || '').trim(), detail: String(m.detailDescription || '').trim() })),
  })).filter(x => x.id);
}

// Entries are identified by the intervention they describe. A solution written for an intervention that is no longer
// in the offer is kept and shown as "orphan" instead of being silently dropped.
export function solutionRows(interventions, solution) {
  const list = interventionList(interventions);
  const known = new Set(list.map(x => x.id));
  const entries = solution?.entries || {};
  const rows = list.map(x => ({ ...x, entry: { ...emptyEntry(), ...(entries[x.id] || {}) }, orphan: false, filled: !isEmptyEntry(entries[x.id]) }));
  Object.keys(entries).filter(id => !known.has(id) && !isEmptyEntry(entries[id])).forEach(id => rows.push({ id, title: 'Intervento non più presente nell’offerta', description: '', activity: '', system: '', requirements: '', mappings: [],
    entry: { ...emptyEntry(), ...entries[id] }, orphan: true, filled: true }));
  return rows;
}

export function solutionProgress(rows) {
  const real = rows.filter(r => !r.orphan);
  return { total: real.length, filled: real.filter(r => r.filled).length, orphans: rows.filter(r => r.orphan).length };
}

export function validateEntry(entry) {
  for (const [key, label] of SOLUTION_FIELDS) if (String(entry?.[key] || '').length > MAX_FIELD) return `«${label}» supera ${MAX_FIELD} caratteri.`;
  return '';
}
export function validateSolution(solution) {
  if (String(solution?.summary || '').length > MAX_SUMMARY) return `La sintesi generale supera ${MAX_SUMMARY} caratteri.`;
  for (const [id, entry] of Object.entries(solution?.entries || {})) { const problem = validateEntry(entry); if (problem) return `Intervento ${id}: ${problem}`; }
  return '';
}

// Updates one field without touching the others; an entry that becomes empty is removed.
export function withField(solution, id, key, value) {
  const entries = { ...(solution?.entries || {}) };
  const next = { ...emptyEntry(), ...(entries[id] || {}), [key]: value };
  if (isEmptyEntry(next)) delete entries[id]; else entries[id] = next;
  return { ...(solution || {}), entries };
}
export const withSummary = (solution, summary) => ({ ...(solution || {}), entries: solution?.entries || {}, summary });

// ---- Markdown for Visual Studio Code ----
const fence = text => String(text || '').replace(/\r\n/g, '\n').trim();
const slug = value => String(value || 'iniziativa').normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^a-zA-Z0-9_-]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 60) || 'iniziativa';
export const solutionFileName = initiative => `SOLUZIONE_${slug(initiative?.code || initiative?.title)}.md`;

export function solutionMarkdown({ initiative = {}, interventions = [], solution = {}, knowledge = [], applications = [], generatedAt = new Date() }) {
  const rows = solutionRows(interventions, solution);
  const confirmed = (knowledge || []).filter(entry => entry.status === 'confermata');
  const lines = [];
  lines.push(`# Soluzione · ${initiative.code ? initiative.code + ' · ' : ''}${initiative.title || 'Iniziativa senza titolo'}`, '');
  lines.push('> Documento per lo sviluppo, da aprire in Visual Studio Code. Il contenuto è scritto e rivisto dal team nel Configuratore Offerta TOW: **non è stato verificato sul codice** né compilato.', '');
  lines.push('| | |', '|---|---|', `| Codice GOTO | ${initiative.code || '—'} |`, `| Sistema | ${initiative.system || '—'} |`, `| Generato il | ${new Date(generatedAt).toLocaleString('it-IT')} |`);
  if (solution.updatedBy) lines.push(`| Ultima modifica | ${solution.updatedBy}${solution.updatedAt ? ' · ' + new Date(solution.updatedAt).toLocaleString('it-IT') : ''} |`);
  lines.push('');
  if (initiative.description) lines.push('## Descrizione dell’iniziativa', '', fence(initiative.description), '');
  if (fence(solution.summary)) lines.push('## Sintesi della soluzione', '', fence(solution.summary), '');
  if (applications.length) lines.push('## Applicativi coinvolti', '', ...applications.map(app => `- **${app.name}**${app.codeUrl ? ` — \`${app.codeUrl}\`` : ''}`), '');
  const progress = solutionProgress(rows);
  lines.push('## Interventi', '', `${progress.filled} interventi su ${progress.total} con soluzione descritta.`, '');
  rows.forEach((row, index) => {
    lines.push(`### ${index + 1}. ${row.id}${row.title ? ' — ' + row.title : ''}`, '');
    if (row.orphan) lines.push('> Questo intervento non è più presente nell’offerta: verificare se la soluzione è ancora valida.', '');
    const meta = [row.system && `Sistema: ${row.system}`, row.activity && `Attività: ${row.activity}`].filter(Boolean);
    if (meta.length) lines.push(meta.join(' · '), '');
    if (row.description) lines.push('**Descrizione dell’intervento**', '', fence(row.description), '');
    if (row.requirements) lines.push('**Copertura requisiti**', '', fence(row.requirements), '');
    if (row.mappings.length) {
      lines.push('**Dettaglio delle attività**', '', '| Voce di catalogo | Tipo | Complessità | Q.tà | Componente | Tecnologia |', '|---|---|---|---|---|---|');
      row.mappings.forEach(m => lines.push(`| ${[m.name, m.type, m.complexity, m.qty || '', m.component, m.technology].map(v => String(v).replace(/\|/g, '\\|')).join(' | ')} |`));
      lines.push('');
    }
    const applicable = confirmed.filter(entry => !entry.interventionId || String(entry.interventionId) === row.id);
    if (applicable.length) lines.push('**Razionali e vincoli confermati**', '', ...applicable.map(entry => `- _${entry.kind}_: ${entry.text}`), '');
    const written = SOLUTION_FIELDS.filter(([key]) => fence(row.entry[key]));
    if (!written.length) lines.push('_Soluzione non ancora descritta per questo intervento._', '');
    written.forEach(([key, label]) => lines.push(`**${label}**`, '', fence(row.entry[key]), ''));
  });
  const general = confirmed.filter(entry => !entry.interventionId);
  if (general.length) lines.push('## Razionali e vincoli generali dell’iniziativa', '', ...general.map(entry => `- _${entry.kind}_: ${entry.text}`), '');
  lines.push('---', '', '_Generato dal Configuratore Offerta TOW. Le sezioni vuote indicano informazioni non ancora fornite dal team._', '');
  return lines.join('\n');
}
